def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        colors = set(v for v in row if v != bg)
        for color in colors:
            cols = [c for c, v in enumerate(row) if v == color]
            if len(cols) >= 2:
                for c in range(cols[0] + 1, cols[-1]):
                    if out[r][c] == bg:
                        out[r][c] = 2
    return out
